export function fn0(a, b, c) {
  const sum = a + b + c;
  if (sum > 10) {
    return sum * 2;
  }
  return sum;
}

class Helper0 {
  constructor(value) {
    this.value = value;
  }

  compute() {
    return this.value * fn0(1, 2, 3);
  }
}
